            modelBuilder.Entity("FormulariosUAF.Models.Domain.Notification", b =>
                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("int")
                        .HasColumnName("IN_COD_NOTIFICACION");

                    SqlServerPropertyBuilderExtensions.UseIdentityColumn(b.Property<int>("Id"));

                    b.Property<DateTime>("CreatedAt")
                        .HasColumnType("datetime2")
                        .HasColumnName("DT_FECHACREACION_NOTIFICACION");

                    b.Property<bool>("IsRead")
                        .HasColumnType("bit")
                        .HasColumnName("BO_LEIDA_NOTIFICACION");

                    b.Property<string>("Message")
                        .IsRequired()
                        .HasColumnType("nvarchar(max)")
                        .HasColumnName("ST_MENSAJE_NOTIFICACION");

                    b.Property<DateTime?>("ReadAt")
                        .HasColumnType("datetime2")
                        .HasColumnName("DT_FECHALECTURA_NOTIFICACION");

                    b.Property<Guid?>("RequestId")
                        .HasColumnType("uniqueidentifier")
                        .HasColumnName("IN_COD_SOLICITUD");

                    b.Property<int>("Type")
                        .HasColumnType("int")
                        .HasColumnName("IN_TIPO_NOTIFICACION");

                    b.Property<string>("UserId")
                        .IsRequired()
                        .HasColumnType("nvarchar(450)")
                        .HasColumnName("IN_COD_USUARIO");

                    b.HasKey("Id");

                    b.HasIndex("CreatedAt");

                    b.HasIndex("UserId");

                    b.HasIndex("UserId", "IsRead");

                    b.ToTable("T_NOTIFICACION");
                });

